-- Refine operational playbooks for cases 4 and 9 from tatiana_2026-09-17_182605.
-- Official Bituah Leumi sources clarify the disability filing window and old-age qualifying-period exemption.

insert into public.sources (slug, publisher, title, url, language, is_official, is_published, checked_on) values
  ('btl-disability-claim-retirement-window', 'Битуах Леуми', 'Подача заявления на общую инвалидность — возрастной срок', 'https://www.btl.gov.il/benefits/Disability/Pages/%D7%94%D7%92%D7%A9%D7%AA%20%D7%94%D7%AA%D7%91%D7%99%D7%A2%D7%94.aspx', 'he', true, true, '2026-09-17'),
  ('btl-old-age-woman-qualifying-exemption', 'Битуах Леуми', 'Женщины, освобождённые от страхового периода для пособия по старости', 'https://www.btl.gov.il/benefits/old_age/Conditions_of_eligibility/achshara/Pages/achsharaIsha.aspx', 'he', true, true, '2026-09-17')
on conflict (slug) do update set
  publisher=excluded.publisher, title=excluded.title, url=excluded.url,
  language=excluded.language, is_official=excluded.is_official,
  is_published=true, checked_on=excluded.checked_on;

insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id,
  'disability-application-retirement-boundary',
  'До какого срока можно подать заявление на общую инвалидность после пенсионного возраста',
  'Заявление на общую инвалидность можно подать начиная с 18 лет и не позднее 12 месяцев после достижения пенсионного возраста. Но условия самого права проверяются применительно к периоду до пенсионного возраста, поэтому дата достижения пенсионного возраста — решающий факт.',
  'Битуах Леуми отдельно указывает срок подачи заявления: до 12 месяцев после пенсионного возраста. Это не означает автоматического возникновения нового права после пенсионного возраста. Для человека, который ещё не достиг пенсионного возраста или достиг его менее 12 месяцев назад, нужно срочно проверить условия и подать заявление, если они выполнялись в соответствующий период. Если прошло больше 12 месяцев, обычный путь первичного заявления на общую инвалидность по этой процедуре закрыт.',
  array['Определите свою точную дату достижения пенсионного возраста.','Если пенсионный возраст ещё не достигнут или с него прошло не более 12 месяцев, проверьте условия общей инвалидности и при наличии основания не откладывайте подачу заявления.','Если прошло больше 12 месяцев, не начинайте с обычного первичного заявления на общую инвалидность; проверьте другие действующие пособия и процедуры, например пересмотр помощи по уходу при ухудшении состояния.'],
  array['Дата рождения','Актуальные медицинские документы','Документы о доходах и работе — если применимо'],
  array['Где вы сейчас относительно своего пенсионного возраста?'],
  array['Срок подачи до 12 месяцев после пенсионного возраста не означает, что после пенсионного возраста автоматически появляется право на новое пособие по общей инвалидности.','Для пожилого человека, уже получающего пособие по уходу, увеличение помощи по уходу оформляется отдельной процедурой повторной проверки.'],
  '[]'::jsonb,
  array['инвалидность','пенсионный возраст','12 месяцев','после пенсии','первичное заявление','нехут клали'],
  'общая инвалидность пожилая женщина после пенсионного возраста можно подать заявление 12 месяцев год после пенсии онкология операция инвалидность метапелет уход'
from public.topics t join public.sources s on s.slug='btl-disability-claim-retirement-window'
where t.slug='disability'
on conflict (slug) do update set
  topic_id=excluded.topic_id, source_id=excluded.source_id, title=excluded.title,
  short_answer=excluded.short_answer, answer=excluded.answer, steps=excluded.steps,
  documents=excluded.documents, follow_up_questions=excluded.follow_up_questions,
  caveats=excluded.caveats, keywords=excluded.keywords, search_text=excluded.search_text,
  is_published=true, reviewed_on='2026-09-17', ai_embedding_allowed=true, embedding=null;

insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id,
  'old-age-disability-recipient-qualifying-exemption',
  'Женщина, получавшая общую инвалидность перед старостью, может быть освобождена от обычного страхового периода',
  'Битуах Леуми указывает, что женщина, получавшая пособие по общей инвалидности в месяце, предшествовавшем началу пособия по старости, относится к женщинам, освобождённым от обычного страхового периода.',
  'Для такой женщины отсутствие обычного трудового/страхового стажа не следует автоматически трактовать как отсутствие права на пособие по старости при пенсионном возрасте. Решающий факт — получала ли она общую инвалидность непосредственно перед переходом на пособие по старости. Это отдельный переходный маршрут от обычного первичного требования накопить страховой период.',
  array['Проверьте решение и фактическую выплату общей инвалидности за месяц перед началом пособия по старости.','При подаче или проверке пособия по старости укажите, что непосредственно перед переходом получали общую инвалидность.','Если Битуах Леуми требует обычный страховой период, попросите проверить применение освобождения для женщины, получавшей общую инвалидность перед старостью.'],
  array['Решение о пособии по общей инвалидности','Подтверждение выплаты за месяц перед переходом','Решение о пособии по старости'],
  array['Получали ли вы пособие по общей инвалидности в месяце перед началом пособия по старости?'],
  array['Освобождение от страхового периода не отменяет проверку других условий пособия по старости и отдельных доходных надбавок.','Сам факт установленного процента инвалидности без получения пособия непосредственно перед переходом — не то же самое, что условие этой карточки.'],
  '[]'::jsonb,
  array['пособие по старости','нет стажа','инвалидность перед пенсией','страховой период','освобождение','женщина'],
  'женщина инвалидность общая пособие месяц перед старостью пенсионный возраст нет трудового стажа страховой период освобождение old age disability transition'
from public.topics t join public.sources s on s.slug='btl-old-age-woman-qualifying-exemption'
where t.slug='old_age'
on conflict (slug) do update set
  topic_id=excluded.topic_id, source_id=excluded.source_id, title=excluded.title,
  short_answer=excluded.short_answer, answer=excluded.answer, steps=excluded.steps,
  documents=excluded.documents, follow_up_questions=excluded.follow_up_questions,
  caveats=excluded.caveats, keywords=excluded.keywords, search_text=excluded.search_text,
  is_published=true, reviewed_on='2026-09-17', ai_embedding_allowed=true, embedding=null;

-- Make the transition card explicitly distinguish an existing beneficiary from a mere disability percentage.
update public.knowledge_cards
set short_answer='Если человек фактически получал общую инвалидность до пенсионного возраста, с пенсионного возраста он переходит на пособие по старости. При этом пособие по старости не должно быть ниже последней месячной выплаты общей инвалидности; при необходимости добавляется доплата по инвалидности.',
    answer='Это отдельный переходный маршрут для фактического получателя общей инвалидности. Поэтому сначала нужно установить не только проценты инвалидности/нетрудоспособности, но и получал ли человек пособие непосредственно до пенсионного возраста. Для женщины, получавшей общую инвалидность в месяце перед началом старости, действует отдельное освобождение от обычного страхового периода. Затем нужно определить пенсионный возраст по дате рождения и проверить первую выплату по старости.',
    steps=array['Проверьте, выплачивалась ли общая инвалидность непосредственно перед пенсионным возрастом.','Определите пенсионный возраст по году и месяцу рождения; для женщины 1966 года рождения возраст по действующей таблице — 64 года независимо от месяца рождения.','После перехода сравните первую выплату по старости с последней месячной выплатой инвалидности.','Если Битуах Леуми требует обычный страховой период, проверьте специальное освобождение для женщины, получавшей общую инвалидность перед старостью.'],
    follow_up_questions=array['Получали ли вы именно пособие по общей инвалидности непосредственно перед пенсионным возрастом, или у вас только установлены медицинский процент и степень нетрудоспособности?'],
    caveats=array['Установленный процент инвалидности сам по себе не доказывает, что человек был получателем пособия непосредственно перед переходом.','Отдельные надбавки и доходные компоненты могут иметь собственные правила.'],
    search_text=search_text || ' фактически получала пособие месяц перед старостью нет стажа освобождение страховой период женщина 1966 месяц рождения не нужен возраст 64',
    embedding=null,
    reviewed_on='2026-09-17'
where slug='disability-to-old-age-transition';

-- For the 1966 cohort the month is relevant to the exact calendar date, not to the retirement-age number itself.
update public.knowledge_cards
set answer='Пенсионный возраст женщин в Израиле постепенно повышается и определяется датой рождения. Для любой женщины, родившейся с января по декабрь 1966 года, таблица Битуах Леуми указывает возраст 64 года. Месяц рождения нужен только для точной календарной даты достижения 64 лет, а не для выбора другого пенсионного возраста.',
    follow_up_questions=array[]::text[],
    caveats=array['Для женщины 1966 года рождения не нужно уточнять месяц, чтобы определить сам пенсионный возраст: он равен 64 годам. Месяц нужен только для точной даты перехода.'],
    search_text=search_text || ' любой месяц 1966 возраст 64 месяц не меняет возраст',
    embedding=null,
    reviewed_on='2026-09-17'
where slug='old-age-retirement-age-woman-1966';
